package net.civeira.phylax.feature.access.userpersonalapikey.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.feature.access.userpersonalapikey.application.visibility.UserPersonalApiKeyEntityEnrichment;
import net.civeira.phylax.feature.identity.user.domain.UserReference;

public class InheritUser {

  /**
   * @autogenerated FormulaPolicyGenerator
   * @param builder
   */
  public void calculate(@Observes UserPersonalApiKeyEntityEnrichment builder) {
    Actor actor = builder.getActor();
    builder.peek(dto -> dto.user(UserReference.of(actor.getUid())));
  }
}
